import json
from PIL import Image
S=1.25
def crop(i,pg,b):
    im=Image.open('/tmp/sci/pages/c4/p-%d.png'%pg); w,h=im.size
    box=tuple(int(v*S) for v in b)
    box=(box[0],box[1],min(box[2],w),min(box[3],h))
    f='/tmp/sci/bookfigs/%s.png'%i; im.crop(box).save(f); return f,'ص'+str(pg).translate(str.maketrans('0123456789','٠١٢٣٤٥٦٧٨٩'))
def E(task,think,steps,answer,why,tip): return dict(task=task,think=think,steps=steps,answer=answer,why=why,tip=tip)
D=[]
def add(i,ex,ma,pg,q,fig=None,conflict=''):
    f,fp=crop(i,*fig) if fig else (None,None)
    D.append(dict(id=i,explain=ex,model_answer=ma,book_page_exact=pg,book_quote=q,book_fig=f,book_fig_page=fp,conflict=conflict))
add('s-001',E('المطلوب: نعرف أي شيء ينقل العدوى.','اسألي نفسك: أي خيار يوصل الجراثيم إلى جسمي؟',['العدوى هي انتقال المرض من مخلوق مصاب إلى سليم.','من طرقها: الطعام المكشوف أو الملوث.','الجراثيم تدخل جسمي مع الأكل الملوث.'],'إذن الجواب كما قالت موضي: أ) تناول طعام ملوث.','ب) تغطية الفم تمنع العدوى. ج) غسل اليدين يحمي. د) الأغذية الصحية تقوي الجسم. بعض الطفلات يخترن خيراً لأنه مكتوب في السؤال عن الطرق.','الطعام الملوث يوصل الجراثيم.'),'أ) تناول طعام ملوث','ص١٥٣','تناول الأطعمة المكشوفة أو شرب المياه الملوثة بمسببات الأمراض.',(153,(155,890,548,1155)))
add('s-006',E('المطلوب: نعرف ما سبب الأنفلونزا.','اسألي نفسك: أي مخلوق دقيق يسبب الزكام والأنفلونزا؟',['الأنفلونزا عدوى فيروسية تصيب الرئتين.','أعراضها تشبه الزكام لكنها أشد.','إذن سببها الفيروس.'],'إذن الجواب كما قالت موضي: أ) الفيروس.','البكتيريا تسبب التهاب الحلق والسل. الفطريات تسبب القدم الرياضي. الديدان ليست في هذا الدرس. تخلط بعض الطفلات بين الفيروس والبكتيريا.','أنفلونزا وزكام: فيروس.'),'أ) الفيروس','ص١٤٤','الأنفلونزا هي عدوى فيروسية تصيب الرئتين والشعب الهوائية.',(144,(1008,585,1400,848)))
add('s-012',E('المطلوب: نصحح الكلمة التي تحتها خط في عبارة عن حماية الجسم.','اسألي نفسك: من يحارب الجراثيم داخل جسمي؟',['خلايا الدم البيضاء مسؤولة عن حماية الجسم ومحاربة الجراثيم.','الجهاز المناعي هو الذي يحمي الجسم من الجراثيم.','فالكلمة الخطأ ليست هي الصحيحة.'],'إذن الجواب كما قالت موضي: الخلايا التنفسية تصبح خلايا الدم البيضاء، والجهاز العضلي يصبح الجهاز المناعي، وفي الاختيار: د) خلايا الدم البيضاء.','الصفائح والبلازما وخلايا الدم الحمراء لا تحارب الجراثيم. الحمراء تنقل الأكسجين، فتخطئ بعض الطفلات.','البيضاء جنود الجسم.'),'خلايا الدم البيضاء / الجهاز المناعي','ص١٥٤','تعد خلايا الدم البيضاء هي الخلايا المسؤولة عن حماية الجسم ومحاربة الأمراض والجراثيم داخل أجسامنا.',(154,(55,1295,1535,1980)))
add('s-015',E('المطلوب: ما اسم الحالة غير الطبيعية التي تؤثر على الجسم؟','اسألي نفسك: ما الفرق بين المرض والعدوى؟',['المرض حالة غير طبيعية تؤثر على جسم المخلوق الحي.','العدوى هي انتقال المرض إلى مخلوق سليم.','إذن التعريف هو تعريف المرض.'],'إذن الجواب كما قالت موضي: المرض.','العدوى هي الانتقال، وليست الحالة نفسها. وكل خيار آخر (التكيف، التكاثر، الماء، المملكة) ليس له علاقة.','مرض = حالة غير طبيعية.'),'المرض','ص١٤٢','يعرف المرض على أنه حالة غير طبيعية تؤثر على جسم المخلوق الحي.')
add('s-019',E('المطلوب: فرق واحد بين المناعة الطبيعية والاصطناعية.','اسألي نفسك: أيهما تدوم أكثر؟ وأيهما نحتاج لها لقاحاً؟',['الطبيعية: استجابة سريعة، وتدوم طويلاً.','الاصطناعية: تأتي بالتطعيم وأخذ اللقاحات.','قد تدوم مدة قصيرة فنأخذ اللقاح أكثر من مرة.'],'إذن الجواب كما قالت موضي: الطبيعية تدوم طويلاً، والاصطناعية تدوم مدة قصيرة ونحتاج اللقاح أكثر من مرة.','تخلط بعض الطفلات بينهما. اللقاح يعني اصطناعية.','لقاح = اصطناعية.'),'الطبيعية تدوم طويلاً، والاصطناعية مدة قصيرة وتحتاج لقاحاً أكثر من مرة','ص١٥٥','وتدوم المناعة الطبيعية طويلاً... هذه المناعة قد تدوم مدة قصيرة فيحتاج الإنسان إلى أخذ اللقاح أكثر من مرة.')
add('s-027',E('المطلوب: نعرف هل ينتقل السكري بالجلوس مع المصاب.','اسألي نفسك: هل السكري تنقله الجراثيم؟',['السكري مرض غير معد.','الأمراض غير المعدية لا تنتقل من المصاب إلى السليم.','إذن نجلس معه عادي، ونكون لطيفات معه.','السمنة أيضاً غير معدية، فعبارة (السمنة معدية) خطأ.'],'إذن الجواب كما قالت موضي: ب) الجلوس معه بشكل طبيعي. وفي الصح والخطأ: السمنة من الأمراض المعدية، خطأ.','الخيار أ يظن أن السكري ينتقل بالمخالطة. وهذا غير صحيح.','السكري والسمنة لا ينتقلان.'),'ب) الجلوس معه بشكل طبيعي / خطأ','ص١٤٢','الأمراض التي لا تنتقل من الشخص المصاب إلى الشخص السليم تسمى الأمراض غير المعدية. مثل السمنة والسكري.',(142,(195,1430,550,1765)))
add('s-043',E('المطلوب: ما الذي ينقل الملاريا؟','اسألي نفسك: ما الحيوان الصغير الذي يلسع ويمص الدم؟',['بعض الحيوانات تنقل المرض وتسمى الناقل الحيوي.','من أمثلتها البعوض والذباب.','الملاريا ينقلها البعوض.'],'إذن الجواب كما قالت موضي: ب) البعوض.','الذباب ينقل أمراضاً أخرى فتخلط بعض الطفلات. الكلاب والقطط ليست ناقلة للملاريا هنا.','ملاريا: بعوض.'),'ب) البعوض','ص١٥٢','أو ما يعرف بالناقل الحيوي كالكلاب والفئران والطيور والبعوض والذباب.')
add('s-046',E('المطلوب: نصحح كلمة السمنة في عبارة عن جهاز المناعة.','اسألي نفسك: أي مرض يحدث عندما يتفاعل جهاز المناعة بشدة؟',['جهاز المناعة يحمينا من المواد الغريبة.','أحياناً يتفاعل بشدة، فيظهر احمرار في الجلد.','هذا اسمه الحساسية.'],'إذن الجواب كما قالت موضي: الحساسية.','السمنة تراكم الدهون في الجسم، وليس لها علاقة بالمناعة.','حساسية: مناعة تغضب.'),'الحساسية','ص١٤٣','الحساسية: هي تفاعل جهاز المناعة بشدة ضد المواد الغريبة.',(143,(200,130,518,335)))
add('s-047',E('المطلوب: ما الذي يسلك سلوك الأحياء أحياناً وغير الأحياء أحياناً؟','اسألي نفسك: أي شيء صغير لا نعرف هل هو حي أم لا؟',['الفيروسات تسلك سلوك المخلوقات الحية أحياناً.','وأحياناً تسلك سلوك الأشياء غير الحية.','تهاجم الجسم وتسبب المرض.'],'إذن الجواب كما قالت موضي: الفيروسات (ب في الاختيار).','البكتيريا والفطريات والطحالب مخلوقات حية دائماً.','فيروس: بين الحي وغير الحي.'),'الفيروسات','ص١٤٤','تسلك الفيروسات سلوك المخلوقات الحية أحياناً وسلوك الأشياء غير الحية أحياناً أخرى.',(144,(1008,155,1400,420)))
add('s-060',E('المطلوب: ما اسم انتقال المرض من مصاب إلى سليم؟','اسألي نفسك: ماذا نسمي الانتقال؟',['العدوى هي انتقال المرض من المخلوق المصاب إلى السليم.','المناعة هي قدرة الجسم على التصدي.','التطعيم يقوي المناعة.'],'إذن الجواب كما قالت موضي: د) العدوى.','الصحة والمناعة والتطعيم كلها حماية، وليست انتقالاً.','عدوى = انتقال.'),'د) العدوى','ص١٥٢','تعرف العدوى بأنها انتقال المرض من المخلوق الحي المصاب إلى المخلوق الحي السليم.')
add('s-061',E('المطلوب: مرض ينتقل من المصاب إلى السليم.','اسألي نفسك: أي مرض تنتقل جراثيمه؟',['الأمراض المعدية تنتقل من مخلوق إلى آخر.','الأنفلونزا عدوى فيروسية.','السكري وضغط الدم وفقر الدم لا تنتقل.'],'إذن الجواب كما قالت موضي: د) الإنفلونزا، وفي السؤال الثاني: ج) المعدية.','السكري وضغط الدم وفقر الدم أمراض غير معدية. يخطئ بعض الطفلات فيخترن مرضاً مشهوراً.','معدي ينتقل، وغير معدي لا ينتقل.'),'د) الإنفلونزا / ج) المعدية','ص١٤٣','الأمراض الناتجة عن الفيروسات والبكتيريا والفطريات الضارة وتنتقل من الشخص المصاب... تسمى بالأمراض المعدية.',(152,(208,1100,600,1365)))
add('s-074',E('المطلوب: نصل كل جملة بالكلمة المناسبة.','اسألي نفسك: ماذا تقول الجملة؟',['٥ الجهاز الهضمي: يفكك الطعام.','٤ الانقراض: اختفاء كل أفراد النوع.','٢ الحساسية: تفاعل المناعة بشدة.','٣ الكوليرا: مرض بكتيري يسبب الإسهال والجفاف.','١ الصفة: خاصية من خصائص المخلوقات الحية.','٦ النواة: تتحكم في أنشطة الخلية.'],'إذن الجواب كما قالت موضي: الجهاز الهضمي=٥، الانقراض=٤، الحساسية=٢، الكوليرا=٣، الصفة=١، النواة=٦.','قد تخلط الطفلة بين الكوليرا والحساسية.','كوليرا: ماء ملوث وإسهال.'),'الجهاز الهضمي=٥؛ الانقراض=٤؛ الحساسية=٢؛ الكوليرا=٣؛ الصفة=١؛ النواة=٦','ص١٤٤ و ص١٤٣','الكوليرا: هو مرض بكتيري عادة ما ينتشر عن طريق شرب الماء الملوث. تتسبب الكوليرا في الإصابة بإسهال وجفاف شديد.')
